import java.lang.reflect.Field;

public class Main {
    static class 小猫 {
        String {f} = "{v}";
    }

    public static void main(String[] args) throws Exception {
        Class<?> 骨架图 = 小猫.class;
        System.out.println(骨架图.getSimpleName());
        for (Field 骨头 : 骨架图.getDeclaredFields()) {
            System.out.println("这根骨头叫 " + 骨头.getName());
        }
    }
}
